SINA_SMART["viro1-rabies"] = {"lecture":"viro1-rabies","title":"Rabies","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"viro1-rabies:e0","text":"Rabies: Lyssavirus, Rhabdoviridae; bullet-shaped, enveloped, (−)ssRNA.","topic":"The disease and the virus","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:e2","text":"Dogs cause ~99% of human cases; bats in the Americas.","topic":"Epidemiology","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:e1","text":"Fatal encephalitis once symptoms start.","topic":"Clinical picture","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:e3","text":"Incubation usually 2-3 months; shorter for bites near the head.","topic":"Clinical picture","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:e4","text":"Early sign: pain or paraesthesia at the bite site.","topic":"Clinical picture","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:e5","text":"Furious (hydrophobia, aerophobia) vs paralytic (~20%).","topic":"Clinical picture","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:s3","text":"Describe and explain: Diagnosis","topic":"Diagnosis","sec":3,"importance":"standard","highYield":"insufficient-source"},{"id":"viro1-rabies:e6","text":"Wash the wound for 15 minutes with soap and water.","topic":"Prevention: PrEP and PEP","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:e7","text":"PEP: vaccine (Essen 0-3-7-14-28 or Zagreb 2-1-1) ± immunoglobulin.","topic":"Prevention: PrEP and PEP","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-rabies:e8","text":"Category III exposure needs vaccine + immunoglobulin.","topic":"Prevention: PrEP and PEP","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1sp6d1i":"a","ofbxl2":"a","rjqpuj":"a","1rankpq":"a","127vi2b":"a","ns5m9j":"a","1toz0or":"a","t8fkf8":"a","1jslrka":"a","1b3bu8n":"a","1gh0ynq":"a","bx9ab5":"a","g3lrld":"a","12782m5":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"viro1-rabies:e0":{"s":0,"u":["Rabies: Lyssavirus, Rhabdoviridae; bullet-shaped, enveloped, (−)ssRNA.","Rabies is a zoonotic, progressive and fatal encephalitis caused by a Lyssavirus (family Rhabdoviridae ).","The virion is bullet-shaped (180 × 75 nm), enveloped , with non-segmented negative-sense RNA (order Mononegavirales) encoding five proteins: G (glycoprotein), N, M, NS (P) and L (polymerase)."],"dp":[]},"viro1-rabies:e2":{"s":1,"u":["Dogs cause ~99% of human cases; bats in the Americas.","In the Americas, where dog rabies has been nearly eliminated, bats now cause most human deaths.","Dogs cause up to 99% of human cases; the urban cycle is maintained by stray dogs, the sylvatic cycle by wild carnivores (and pets in contact with them)."],"dp":[]},"viro1-rabies:e1":{"s":2,"u":["Fatal encephalitis once symptoms start.","Once symptoms appear, rabies is almost always fatal."],"dp":[]},"viro1-rabies:e3":{"s":2,"u":["Incubation usually 2-3 months; shorter for bites near the head.","Incubation is usually 2-3 months (from under a week to over a year), depending on the site of entry (closer to the brain = shorter) and viral load."],"dp":[]},"viro1-rabies:e4":{"s":2,"u":["Early sign: pain or paraesthesia at the bite site.","Early signs: fever and pain, tingling, itching or burning at the bite site .","Paralytic rabies (~20%): ascending paralysis from the bite site and slow coma; often misdiagnosed."],"dp":[]},"viro1-rabies:e5":{"s":2,"u":["Furious (hydrophobia, aerophobia) vs paralytic (~20%).","Furious rabies (most cases): hyperactivity, agitation, hydrophobia , aerophobia , hallucinations; death in a few days from cardiorespiratory arrest.","Paralytic rabies (~20%): ascending paralysis from the bite site and slow coma; often misdiagnosed."],"dp":[]},"viro1-rabies:s3":{"s":3,"u":["No test detects rabies before symptoms.","Without hydrophobia or aerophobia, clinical diagnosis is hard."],"dp":[]},"viro1-rabies:e6":{"s":4,"u":["Wash the wound for 15 minutes with soap and water.","Post-exposure prophylaxis is an emergency: (1) wash the wound for at least 15 minutes with soap and water, detergent or povidone-iodine; (2) a course of WHO-standard vaccine (e.g.","WHO categories: I (touch, lick on intact skin): wash only; II (nibble, minor scratch without bleeding): wash + vaccine; III (transdermal bite or scratch, saliva on mucosa or broken skin, bat contact): wash + vaccine + immunoglobulin."],"dp":[]},"viro1-rabies:e7":{"s":4,"u":["PEP: vaccine (Essen 0-3-7-14-28 or Zagreb 2-1-1) ± immunoglobulin.","Schedules used in Morocco for unvaccinated people: Essen (5 doses IM on days 0, 3, 7, 14, 28) and Zagreb (2-1-1: two doses on day 0, then days 7 and 21).","Verorab); (3) rabies immunoglobulin when indicated."],"dp":[]},"viro1-rabies:e8":{"s":4,"u":["Category III exposure needs vaccine + immunoglobulin.","WHO categories: I (touch, lick on intact skin): wash only; II (nibble, minor scratch without bleeding): wash + vaccine; III (transdermal bite or scratch, saliva on mucosa or broken skin, bat contact): wash + vaccine + immunoglobulin.","Post-exposure prophylaxis is an emergency: (1) wash the wound for at least 15 minutes with soap and water, detergent or povidone-iodine; (2) a course of WHO-standard vaccine (e.g."],"dp":[{"h":"Why rabies vaccine works after the bite","t":"Almost every vaccine must be given before exposure. Rabies is the exception because the virus travels slowly along peripheral nerves, often for weeks, before reaching the brain. That delay gives the vaccine time to produce neutralising antibodies, and immunoglobulin injected into the wound neutralises virus locally in the meantime. Once the virus reaches the CNS and symptoms start, the window has closed, which is why PEP must never be delayed."}]}},"meta":{"1sp6d1i":{"a":"recall","vg":"viro1-rabies:e0/recall/1"},"ofbxl2":{"a":"recall","vg":"viro1-rabies:e0/recall/2"},"rjqpuj":{"a":"recall","vg":"viro1-rabies:e2/recall/1"},"1rankpq":{"a":"recall","vg":"viro1-rabies:e3/recall/1"},"127vi2b":{"a":"recall","vg":"viro1-rabies:e4/recall/1"},"ns5m9j":{"a":"recall","vg":"viro1-rabies:e5/recall/1"},"1toz0or":{"a":"recall","vg":"viro1-rabies:e6/recall/1"},"t8fkf8":{"a":"recall","vg":"viro1-rabies:e8/recall/1"},"1jslrka":{"a":"recall","vg":"viro1-rabies:e8/recall/2"},"1b3bu8n":{"a":"recall","vg":"viro1-rabies:e7/recall/1"},"1gh0ynq":{"a":"recall","vg":"viro1-rabies:e8/recall/3"},"bx9ab5":{"a":"recall","vg":"viro1-rabies:e8/recall/4"},"g3lrld":{"a":"relationship","vg":"viro1-rabies:e2/relationship/1"},"12782m5":{"a":"recall","vg":"viro1-rabies:e8/recall/5"}},"explRev":"70da4bfb1146"};
